import path from 'node:path';
import os from 'node:os';
import { config as loadDotenv } from 'dotenv';
loadDotenv();
export type Config = { supabaseUrl: string; serviceRoleKey: string; anywaysRepoPath: string; ollamaBaseUrl: string; ollamaModel: string; codexExecutable: string; pipelineV1Enabled: boolean; pipelineV1AllowedJobId: string | null; controllerId: string; pollIntervalMs: number; leaseSeconds: number; heartbeatMs: number; idleMs: number; minimumMemoryGb: number; healthHost: string; healthPort: number; logDirectory: string; jobTimeoutMs: number; phase2JobTimeoutMs: number; childKillGraceMs: number; maxAttempts: number; retryDelaySeconds: number; };
const required = (name: string) => { const value = process.env[name]?.trim(); if (!value) throw new Error(`${name} is required`); return value; };
const integer = (name: string, fallback: number, min = 1) => { const value = Number(process.env[name] || fallback); if (!Number.isInteger(value) || value < min) throw new Error(`${name} must be an integer >= ${min}`); return value; };
export function readConfig(): Config { return { supabaseUrl: required('SUPABASE_URL'), serviceRoleKey: required('SUPABASE_SERVICE_ROLE_KEY'), anywaysRepoPath: process.env.ANYWAYS_REPO_PATH || '/Volumes/External/GitHub/IGNORED/anyways', ollamaBaseUrl: process.env.OLLAMA_BASE_URL || 'http://127.0.0.1:11434', ollamaModel: process.env.OLLAMA_MODEL || 'qwen3:14b', codexExecutable: process.env.ANYWAYS_CODEX_BIN?.trim() || path.join(path.dirname(process.execPath), 'codex'), pipelineV1Enabled: /^(1|true|yes)$/i.test(process.env.PIPELINE_V1_ENABLED || ''), pipelineV1AllowedJobId: process.env.PIPELINE_V1_ALLOWED_JOB_ID?.trim() || null, controllerId: process.env.CONTROLLER_ID || `${os.hostname()}-${process.pid}`, pollIntervalMs: integer('POLL_INTERVAL_SECONDS', 5) * 1000, leaseSeconds: integer('LEASE_DURATION_SECONDS', 120, 30), heartbeatMs: integer('HEARTBEAT_INTERVAL_SECONDS', 30) * 1000, idleMs: integer('MODEL_IDLE_TIMEOUT_MINUTES', 10) * 60_000, minimumMemoryGb: integer('MINIMUM_AVAILABLE_MEMORY_GB', 6), healthHost: process.env.HEALTH_HOST || '127.0.0.1', healthPort: integer('HEALTH_PORT', 4317), logDirectory: process.env.LOG_DIRECTORY || path.join(os.homedir(), 'Library/Logs/AnywaysController'), jobTimeoutMs: integer('JOB_TIMEOUT_SECONDS', 900) * 1000, phase2JobTimeoutMs: integer('PHASE2_JOB_TIMEOUT_SECONDS', 2400) * 1000, childKillGraceMs: integer('CHILD_KILL_GRACE_SECONDS', 5) * 1000, maxAttempts: integer('MAX_ATTEMPTS', 3), retryDelaySeconds: integer('BASE_RETRY_DELAY_SECONDS', 60) }; }
